import sys

def is_prime(x):
    if x < 2:
        return False
    if x < 4:
        return True
    if x % 2 == 0 or x % 3 == 0:
        return False
    i = 5
    while i * i <= x:
        if x % i == 0 or x % (i + 2) == 0:
            return False
        i += 6
    return True

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    best = 0
    for i in range(n):
        for c in (i, n - 1 - i):
            v = int(data[1 + i * n + c])
            if v > best and is_prime(v):
                best = v
    print(best)

main()

